local OMIT={events=true,inputText=true,freeText=true,lastFreeText=true,typedText=true,lastTypedText=true,inputHistory=true,transcript=true,rawInput=true,composition=true,preedit=true,candidates=true,resolved=true,lastResolved=true,pendingSemantic=true,semanticHistory=true,strokeHistory=true,inputBuffer=true,freeBuffer=true,lastSemantic=true,seenStrokeIds=true,seenSemanticIds=true,seenSegmentIds=true,acceptedStrokeIds=true,acceptedSemanticIds=true,acceptedSegments=true,semanticCategoryCounts=true,command=true,commandAt=true,__proto__=true,constructor=true,prototype=true}
local function array(v)
 if type(v)~='table' or v==JSON.null then return false end
 local mt=getmetatable(v);if mt and mt.__js_object then return false end
 return mt and mt.__js_array==true or v[1]~=nil or next(v)==nil
end
local function list()return setmetatable({},{__js_array=true})end
local function object()return setmetatable({},{__js_object=true,__nulls={}})end
local function record(v)return type(v)=='table' and v~=JSON.null and not array(v)end
local function finite(v)return type(v)=='number' and v==v and v~=math.huge and v~=-math.huge end
local function normalize(text)
 local points={}
 for _,cp in ipairs(C.codepoints(text))do
  if cp>=44032 and cp<55204 then local s=cp-44032;points[#points+1]=4352+math.floor(s/588);points[#points+1]=4449+math.floor(s%588/28);if s%28~=0 then points[#points+1]=4519+s%28 end
  elseif DECOMP[cp] then for _,v in ipairs(DECOMP[cp])do points[#points+1]=v end
  else points[#points+1]=cp end
 end
 for i=2,#points do local cp,j=points[i],i;local cls=CCC[cp] or 0;if cls>0 then while j>1 and (CCC[points[j-1]] or 0)>cls do points[j]=points[j-1];j=j-1 end;points[j]=cp end end
 local out,starter,starterAt,lastClass={},nil,nil,0
 for _,cp in ipairs(points)do
  local cls=CCC[cp] or 0;local combined
  if starter and (lastClass<cls or lastClass==0)then
   if starter>=4352 and starter<4371 and cp>=4449 and cp<4470 then combined=44032+(starter-4352)*588+(cp-4449)*28
   elseif starter>=44032 and starter<55204 and (starter-44032)%28==0 and cp>4519 and cp<4547 then combined=starter+cp-4519
   elseif COMPOSE[starter]then combined=COMPOSE[starter][cp] end
  end
  if combined then out[starterAt]=combined;starter=combined
  else out[#out+1]=cp;if cls==0 then starter=cp;starterAt=#out end;lastClass=cls end
 end
 local chars={};for _,cp in ipairs(out)do chars[#chars+1]=C.utf8(cp) end;return table.concat(chars)
end
local function whitespace(cp)return cp>=9 and cp<=13 or cp==32 or cp==160 or cp==5760 or cp>=8192 and cp<=8202 or cp==8232 or cp==8233 or cp==8239 or cp==8287 or cp==12288 or cp==65279 end
local function trim(text)
 local p=C.codepoints(text);local first,last=1,#p
 while first<=last and whitespace(p[first])do first=first+1 end;while last>=first and whitespace(p[last])do last=last-1 end
 local out={};for i=first,last do out[#out+1]=C.utf8(p[i]) end;return table.concat(out)
end
local function scrub(value,depth)
 depth=depth or 0;if depth>24 then error('存档嵌套过深。')end
 if type(value)=='number' and not finite(value)then error('存档含无效数值。')end
 if value==JSON.null then return JSON.null end
 if array(value)then local out=list();for i=1,#value do out[i]=type(value[i])=='function' and JSON.null or scrub(value[i],depth+1)end;return out end
 if type(value)=='table'then
  local out=object();for key,v in pairs(value)do if type(key)=='string' and not OMIT[key] and type(v)~='function'then out[key]=scrub(v,depth+1)end end
  local mt=getmetatable(value);if mt and mt.__nulls then for key in pairs(mt.__nulls)do if not OMIT[key] and value[key]==nil then getmetatable(out).__nulls[key]=true end end end
  return out
 end
 if type(value)=='string' and C.jsLength(value)>8192 then error('存档中存在过长文本。')end
 return value
end
local function validateGame(value)
 if not record(value)or value.version~=2 or not finite(value.seed)or not PHASES[value.phase]then error('存档格式或版本不兼容。')end
 return scrub(value)
end
local function wordEntry(value)
 if not record(value)or type(value.word)~='string'or type(value.pinyin)~='string'or type(value.category)~='string'then error('词库条目不完整。')end
 local word=trim(normalize(value.word));local pinyin=C.jsLower(trim(value.pinyin));local category=trim(value.category);local source=value.source;if source==nil then source='favorite'end
 if source~='favorite'and source~='story'then error('仅能保存明确收藏或剧情解锁的词。')end
 local valid=word~=''and #C.codepoints(word)<=32 and C.jsLength(pinyin)<=128 and category~=''and C.jsLength(category)<=32
 for _,cp in ipairs(C.codepoints(word))do if cp<32 or cp==127 then valid=false end end
 for _,cp in ipairs(C.codepoints(pinyin))do if not(cp>=97 and cp<=122 or cp==252 or cp==39 or cp==32 or cp==58 or cp==45)then valid=false end end
 if not valid then error('词语、拼音或分类不符合要求。')end
 if not finite(value.uses)or value.uses<0 or value.uses>9007199254740991 or value.uses%1~=0 or not finite(value.mastery)or value.mastery<0 then error('词库熟练度或次数无效。')end
 return {word=word,pinyin=pinyin,category=category,uses=value.uses,mastery=value.mastery,source=source}
end
local function cleanWords(words,limit,duplicates)
 if not array(words)or limit and #words>limit then error('不是兼容的火苗存档。')end
 local out,seen=list(),{}
 for _,entry in ipairs(words)do local clean=wordEntry(entry);local old=seen[clean.word]
  if old then if duplicates then error('导入词库包含重复词语。')else out[old]=clean end else out[#out+1]=clean;seen[clean.word]=#out end
 end;return out
end
-- JSON.parse rejects leading zeros, missing fraction digits and trailing commas;
-- the small shared codec deliberately accepts a wider number token, so validate grammar first.
local function strictJSON(text)
 local i,n=1,#text;local stack={};local root=false
 local function skip()while i<=n and text:sub(i,i):find('[ \t\r\n]')do i=i+1 end end
 local function stringToken()
  assert(text:sub(i,i)=='"');i=i+1
  while i<=n do local b=text:byte(i);i=i+1;if b==34 then return end
   if b==92 then local e=text:sub(i,i);i=i+1;if e=='u'then assert(text:sub(i,i+3):match('^%x%x%x%x$'));i=i+4 else assert(e~=''and('"\\/bfnrt'):find(e,1,true))end
   else assert(b>=32)end
  end;error('Unterminated JSON string')
 end
 local function value()
  skip();local c=text:sub(i,i)
  if c=='{'then i=i+1;stack[#stack+1]={kind='object',state='first'}
  elseif c=='['then i=i+1;stack[#stack+1]={kind='array',state='first'}
  elseif c=='"'then stringToken()
  elseif c=='t'then assert(text:sub(i,i+3)=='true');i=i+4
  elseif c=='f'then assert(text:sub(i,i+4)=='false');i=i+5
  elseif c=='n'then assert(text:sub(i,i+3)=='null');i=i+4
  else
   if c=='-'then i=i+1;c=text:sub(i,i)end
   if c=='0'then i=i+1 else assert(c:match('^[1-9]$'));repeat i=i+1 until not text:sub(i,i):match('^%d$')end
   if text:sub(i,i)=='.'then i=i+1;assert(text:sub(i,i):match('^%d$'));repeat i=i+1 until not text:sub(i,i):match('^%d$')end
   c=text:sub(i,i);if c=='e'or c=='E'then i=i+1;c=text:sub(i,i);if c=='+'or c=='-'then i=i+1 end;assert(text:sub(i,i):match('^%d$'));repeat i=i+1 until not text:sub(i,i):match('^%d$')end
  end
 end
 while true do
  skip();local frame=stack[#stack]
  if not frame then if root then assert(i>n);return else root=true;value()end
  elseif frame.kind=='array'then
   if frame.state=='first'and text:sub(i,i)==']'then stack[#stack]=nil;i=i+1
   elseif frame.state=='first'or frame.state=='value'then frame.state='comma';value()
   else local c=text:sub(i,i);i=i+1;if c==']'then stack[#stack]=nil else assert(c==',');frame.state='value'end end
  else
   if frame.state=='first'and text:sub(i,i)=='}'then stack[#stack]=nil;i=i+1
   elseif frame.state=='first'or frame.state=='key'then stringToken();frame.state='colon'
   elseif frame.state=='colon'then assert(text:sub(i,i)==':');i=i+1;frame.state='value'
   elseif frame.state=='value'then frame.state='comma';value()
   else local c=text:sub(i,i);i=i+1;if c=='}'then stack[#stack]=nil else assert(c==',');frame.state='key'end end
  end
 end
end
local function decode(text)
 local ok,value=pcall(function()strictJSON(text);return JSON.parse(text)end)
 if not ok then error('存档无法读取，请选择从《火苗》导出的JSON文件。')end;return value
end
local function envelope(state,words)
 return {format=FORMAT,version=2,exportedAt=os.date('!%Y-%m-%dT%H:%M:%S.000Z'),game=state~=nil and validateGame(state)or JSON.null,words=cleanWords(words or list(),nil,false)}
end
function Storage.new(options)
 options=options or {}
 -- 使用项目、用户隔离的相对路径，不访问沙箱禁止的系统目录。
 return setmetatable({path=options.testMode and 'huomiao-acceptance-v2.json'or 'huomiao-local-v2.json'},Storage)
end
function Storage:_read(path)
 local file=File();assert(file:Open(path,FILE_READ),'本地存档无法打开。')
 local ok,value=pcall(function()
  local lines={};while not file:IsEof()do lines[#lines+1]=file:ReadLine()end
  return decode(table.concat(lines,'\n'))
 end);file:Close();if not ok then error(value)end;return value
end
function Storage:_write(state,words)
 local text=JSON.stringify(envelope(state,words));local target=self.path;local temp=target..'.tmp';local backup=target..'.bak'
 local file=File();assert(file:Open(temp,FILE_WRITE),'本地保存未完成。')
 local ok,value=pcall(function()assert(file:WriteLine(text),'本地保存失败。');file:Flush()end);file:Close();if not ok then error(value)end
 -- Validate the completed temporary file before replacing the previous transaction.
 self:_read(temp)
 local hadCurrent=fileSystem:FileExists(target)
 if hadCurrent then
  if fileSystem:FileExists(backup)then assert(fileSystem:Delete(backup),'上一次存档备份无法更新。')end
  assert(fileSystem:Rename(target,backup),'本地保存未完成，旧进度仍保留。')
 end
 if not fileSystem:Rename(temp,target)then
  if hadCurrent then local restored=fileSystem:Rename(backup,target);if not restored then error('本地保存未完成，进度保存在备份文件中。')end end
  error('本地保存未完成。')
 end
end
function Storage:load()
 local path=self.path;if not fileSystem:FileExists(path)then if fileSystem:FileExists(path..'.bak')then path=path..'.bak'else return nil,list()end end
 local v=self:_read(path)
 if not record(v)or v.format~=FORMAT or v.version~=2 then error('本地存档版本不兼容。')end
 local game=not C.jsNullProperty(v,'game')and validateGame(v.game)or nil
 local words=cleanWords(v.words,nil,false)
 table.sort(words,function(a,b)if a.mastery~=b.mastery then return a.mastery>b.mastery elseif a.uses~=b.uses then return a.uses>b.uses else return a.word<b.word end end)
 return game,words
end
function Storage:save(state,words)self:_write(state,words)end
function Storage:export(state,words)return JSON.stringify(envelope(state,words))end
function Storage:prepareImport(text)
 if type(text)~='string'then error('存档无法读取，请选择从《火苗》导出的JSON文件。')end
 if #text>2000000 then error('存档文件超过2MB。')end
 local v=decode(text)
 if not record(v)or v.format~=FORMAT or(v.version~=1 and v.version~=2)or not array(v.words)or #v.words>2000 then error('不是兼容的火苗存档。')end
 local game=v.version==2 and not C.jsNullProperty(v,'game')and validateGame(v.game)or nil
 local words=cleanWords(v.words,2000,true)
 return {version=v.version,game=game,words=words,gameImported=game~=nil}
end
function Storage:applyImport(pending,currentState,currentWords)
 if type(pending)~='table'or(pending.version~=1 and pending.version~=2)then error('不是兼容的火苗存档。')end
 local incoming=cleanWords(pending.words,2000,true)
 if pending.version==1 then
  local merged=cleanWords(currentWords or list(),nil,false);local index={};for _,word in ipairs(merged)do index[word.word]=word end
  for _,word in ipairs(incoming)do local old=index[word.word];if old then old.uses=math.max(old.uses,word.uses);old.mastery=math.max(old.mastery,word.mastery)else merged[#merged+1]=word;index[word.word]=word end end
  local stored=self:load();self:_write(stored,merged);return currentState,merged
 end
 local game=pending.game and validateGame(pending.game)or nil;self:_write(game,incoming);return game,incoming
end
return Storage
